package com.blackeye.klipnote

import android.content.Context
import android.webkit.CookieManager
import java.io.File

/**
 * Cookies Netscape locales (estilo Seal) para yt-dlp `--cookies`.
 * Solo en [Context.getFilesDir]; nunca se suben.
 */
object CookieStore {
    private const val PREFS = "klipnote_cookies"
    private const val KEY_ENABLED = "cookies_enabled"
    private const val KEY_USER_AGENT = "cookies_user_agent"
    private const val FILE_NAME = "cookies.txt"

    const val COOKIE_HEADER =
        "# Netscape HTTP Cookie File\n# Auto-generated by KlipNote WebView\n"

    private val IG_COOKIE_URLS = listOf(
        "https://www.instagram.com/",
        "https://instagram.com/",
        "https://m.instagram.com/",
        "https://www.instagram.com/accounts/login/"
    )

    fun cookiesFile(context: Context): File =
        File(context.applicationContext.filesDir, FILE_NAME)

    fun hasCookies(context: Context): Boolean {
        val f = cookiesFile(context)
        return f.isFile && f.length() > COOKIE_HEADER.length.toLong()
    }

    fun isEnabled(context: Context): Boolean =
        prefs(context).getBoolean(KEY_ENABLED, true)

    fun setEnabled(context: Context, enabled: Boolean) {
        prefs(context).edit().putBoolean(KEY_ENABLED, enabled).apply()
    }

    fun cookiesFileIfEnabled(context: Context): File? {
        if (!isEnabled(context)) return null
        val f = cookiesFile(context)
        return if (f.isFile && f.length() > 0L) f else null
    }

    fun userAgent(context: Context): String? =
        prefs(context).getString(KEY_USER_AGENT, null)?.takeIf { it.isNotBlank() }

    fun saveUserAgent(context: Context, userAgent: String?) {
        prefs(context).edit().putString(KEY_USER_AGENT, userAgent?.takeIf { it.isNotBlank() }).apply()
    }

    fun statusLabel(context: Context): String {
        return when {
            !hasCookies(context) -> "Sin cookies de Instagram"
            !isEnabled(context) -> "Cookies guardadas (desactivadas)"
            else -> "Cookies Instagram listas"
        }
    }

    /**
     * Extrae cookies de CookieManager para dominios Instagram abiertos
     * y escribe Netscape a filesDir/cookies.txt.
     */
    fun saveFromCookieManager(context: Context, userAgent: String? = null): Int {
        val app = context.applicationContext
        val manager = CookieManager.getInstance()
        runCatching { manager.flush() }

        val rows = linkedMapOf<String, String>()
        for (url in IG_COOKIE_URLS) {
            val header = manager.getCookie(url) ?: continue
            parseCookieHeader(header).forEach { (name, value) ->
                rows[name] = value
            }
        }
        if (rows.isEmpty()) {
            throw IllegalStateException(
                "No hay cookies de Instagram. Inicia sesión en el WebView primero."
            )
        }

        val body = buildString {
            append(COOKIE_HEADER)
            rows.forEach { (name, value) ->
                append(netscapeLine(".instagram.com", name, value))
                append('\n')
            }
        }
        val file = cookiesFile(app)
        file.writeText(body)
        setEnabled(app, true)
        if (!userAgent.isNullOrBlank()) {
            saveUserAgent(app, userAgent)
        }
        return rows.size
    }

    /** Pega un cookies.txt Netscape (o líneas name=value) y lo guarda en privado. */
    fun saveFromPaste(context: Context, raw: String): Int {
        val text = raw.trim()
        if (text.isBlank()) throw IllegalArgumentException("Pegado vacío")

        val normalized = if (text.contains('\t') || text.contains("# Netscape")) {
            if (text.startsWith("#")) text else COOKIE_HEADER + text.trimStart() + "\n"
        } else {
            val pairs = parseCookieHeader(text.replace('\n', ';'))
            if (pairs.isEmpty()) {
                throw IllegalArgumentException("Formato de cookies no reconocido")
            }
            buildString {
                append(COOKIE_HEADER)
                pairs.forEach { (name, value) ->
                    append(netscapeLine(".instagram.com", name, value))
                    append('\n')
                }
            }
        }

        val file = cookiesFile(context.applicationContext)
        file.writeText(normalized)
        setEnabled(context.applicationContext, true)
        return normalized.lineSequence().count { line ->
            val t = line.trim()
            t.isNotEmpty() && !t.startsWith("#") && t.contains('\t')
        }
    }

    fun clear(context: Context) {
        val app = context.applicationContext
        runCatching { cookiesFile(app).delete() }
        saveUserAgent(app, null)
        setEnabled(app, false)
        runCatching {
            val manager = CookieManager.getInstance()
            manager.removeAllCookies(null)
            manager.flush()
        }
    }

    private fun parseCookieHeader(header: String): List<Pair<String, String>> {
        return header.split(';')
            .map { it.trim() }
            .filter { it.isNotEmpty() && it.contains('=') }
            .mapNotNull { part ->
                val eq = part.indexOf('=')
                if (eq <= 0) return@mapNotNull null
                val name = part.substring(0, eq).trim()
                val value = part.substring(eq + 1).trim()
                if (name.isEmpty()) null else name to value
            }
    }

    private fun netscapeLine(domain: String, name: String, value: String): String {
        // domain \t includeSubdomains \t path \t secure \t expiry \t name \t value
        return listOf(
            domain,
            "TRUE",
            "/",
            "TRUE",
            "0",
            name,
            value
        ).joinToString("\t")
    }

    private fun prefs(context: Context) =
        context.applicationContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
}
